            throw new SearchException('Fields list must not be null or empty');
        }

        List<String> selectParts = new List<String>{ 'Id' };
        Set<String> selectedFieldsSet = new Set<String>{ 'Id' };
        for (String field : fields) {
            if (String.isBlank(field)) {
                throw new SearchException('Field name cannot be blank');
            }
            String resolvedField = resolveFieldName(fieldMap, field);
            if (resolvedField == null) {
                throw new SearchException('Field not found on object ' + resolvedObjectName + ': ' + field);
            }
            Schema.FieldDescribe fd = fieldMap.get(resolvedField).getDescribe();
            if (!fd.isAccessible()) {
                throw new SearchException('User does not have read access to field: ' + field);
            }
            if (!selectedFieldsSet.contains(resolvedField)) {
                selectParts.add(resolvedField);
                selectedFieldsSet.add(resolvedField);
            }
        }

        List<String> whereParts = new List<String>();
        if (filters != null && !filters.isEmpty()) {
            for (String filterKey : filters.keySet()) {
                if (String.isBlank(filterKey)) {
