            throw new PayloadException('Line is missing sku');
        }

        // quantity
        Object qtyObj = m.get('quantity');
        if (qtyObj == null) {
            throw new PayloadException('Line is missing quantity');
        }
        Integer quantity;
        if (qtyObj instanceof Integer) {
            quantity = (Integer) qtyObj;
        } else if (qtyObj instanceof Decimal) {
            quantity = (Integer) qtyObj;
        } else {
            throw new PayloadException('Line quantity must be a number');
        }
        if (quantity <= 0) {
            throw new PayloadException('Line quantity must be positive');
        }

        // unitPrice
        Object priceObj = m.get('unitPrice');
        if (priceObj == null) {
            throw new PayloadException('Line is missing unitPrice');
        }
        Decimal unitPrice;
        if (priceObj instanceof Integer) {
