            throw new PayloadException('Request body is not valid JSON.');
        }

        if (root == null || !(root instanceof Map<String, Object>)) {
            throw new PayloadException('Request body must be a JSON object.');
        }

        Map<String, Object> map = (Map<String, Object>) root;

        // --- number (required, non-blank string) ---
        if (!map.containsKey('number') || map.get('number') == null) {
            throw new PayloadException('Missing required field "number".');
        }
        if (!(map.get('number') instanceof String) || ((String) map.get('number')).trim().isEmpty()) {
            throw new PayloadException('"number" must be a non-blank string.');
        }

        Order order = new Order();
        order.orderNumber = (String) map.get('number');

        // --- date (optional, ISO yyyy-MM-dd) ---
        if (map.containsKey('date') && map.get('date') != null && map.get('date') instanceof String) {
            try {
                order.orderDate = Date.valueOf((String) map.get('date'));
            } catch (Exception e) {
                order.orderDate = null;
            }
        }

        // --- currency (optional) ---
        if (map.containsKey('currency') && map.get('currency') != null && map.get('currency') instanceof String) {
            order.currencyCode = (String) map.get('currency');
        }

        // --- customer (optional) ---
        if (map.containsKey('customer') && map.get('customer') != null
                && map.get('customer') instanceof Map<String, Object>) {
            Map<String, Object> custMap = (Map<String, Object>) map.get('customer');
            if (custMap.containsKey('email') && custMap.get('email') != null
                    && custMap.get('email') instanceof String) {
                order.customerEmail = (String) custMap.get('email');
            }
        }

        // --- lines ---
        order.lines = new List<Line>();
        Decimal total = 0;

        if (map.containsKey('lines') && map.get('lines') != null
                && map.get('lines') instanceof List<Object>) {
            List<Object> linesArr = (List<Object>) map.get('lines');
            for (Integer i = 0; i < linesArr.size(); i++) {
                if (!(linesArr[i] instanceof Map<String, Object>)) {
                    throw new PayloadException('Line at index ' + i + ' is not a JSON object.');
                }
                Map<String, Object> lm = (Map<String, Object>) linesArr[i];

                // sku (required)
                if (!lm.containsKey('sku') || lm.get('sku') == null
                        || !(lm.get('sku') instanceof String)
                        || ((String) lm.get('sku')).trim().isEmpty()) {
                    throw new PayloadException('Missing or invalid "sku" in line ' + i + '.');
                }

                // quantity (required, must be positive)
                if (!lm.containsKey('quantity') || lm.get('quantity') == null) {
                    throw new PayloadException('Missing "quantity" in line ' + i + '.');
                }
                Integer qty;
                if (lm.get('quantity') instanceof Integer) {
                    qty = (Integer) lm.get('quantity');
                } else if (lm.get('quantity') instanceof Double) {
                    qty = (Integer) (Double) lm.get('quantity');
                } else {
                    throw new PayloadException('Invalid "quantity" type in line ' + i + '.');
                }
                if (qty <= 0) {
                    throw new PayloadException('"quantity" must be a positive integer in line ' + i + '.');
                }

                // unitPrice (required, must be non-negative)
                if (!lm.containsKey('unitPrice') || lm.get('unitPrice') == null) {
                    throw new PayloadException('Missing "unitPrice" in line ' + i + '.');
                }
                Decimal price;
                if (lm.get('unitPrice') instanceof Integer) {
                    price = (Decimal) (Integer) lm.get('unitPrice');
                } else if (lm.get('unitPrice') instanceof Double) {
                    price = (Decimal) (Double) lm.get('unitPrice');
                } else {
                    throw new PayloadException('Invalid "unitPrice" type in line ' + i + '.');
                }
                if (price < 0) {
                    throw new PayloadException('"unitPrice" must be non-negative in line ' + i + '.');
                }

                // discount (optional, defaults to 0)
                Decimal disc = 0;
                if (lm.containsKey('discount') && lm.get('discount') != null) {
                    if (lm.get('discount') instanceof Integer) {
                        disc = (Decimal) (Integer) lm.get('discount');
                    } else if (lm.get('discount') instanceof Double) {
                        disc = (Decimal) (Double) lm.get('discount');
                    }
                }

                // lineTotal = quantity * unitPrice * (1 - discount), half-up to 2 dp
                Decimal raw = (Decimal) qty * price * ((Decimal) 1 - disc);
                Decimal lineTotal = (Decimal) System.Math.round(raw.doubleValue() * 100) / 100;

                Line line = new Line();
                line.sku = (String) lm.get('sku');
                line.quantity = qty;
                line.unitPrice = price;
                line.discount = disc;
                line.lineTotal = lineTotal;

                order.lines.add(line);
                total += lineTotal;
            }
        }

        order.total = total;
        return order;
    }

    public static String toAcknowledgement(Order order) {
        Map<String, Object> ack = new Map<String, Object>{
            'number' => order.orderNumber,
            'status' => 'RECEIVED',
            'lineCount' => (order.lines == null ? 0 : order.lines.size()),
            'total' => (order.total == null ? 0 : order.total)
        };
        return JSON.serialize(ack);
    }
}
