        // Build map keyed by upper-cased order number so the last event in the
        // list wins for each order.  Uppercasing guarantees a match with the
        // FB_Sales_Order__c.Order_Number__c field which is always stored upper-case.
        Map<String, FB_Shipment_Event__e> latestByOrder = new Map<String, FB_Shipment_Event__e>();
        for (FB_Shipment_Event__e e : events) {
            if (e == null || e.Order_Number__c == null || e.Order_Number__c.trim().isEmpty()) {
                continue;
            }
            latestByOrder.put(e.Order_Number__c.toUpperCase(), e);
        }

        if (latestByOrder.isEmpty()) {
            return;
        }

        // One SOQL – fetch all non-cancelled orders that match the event order numbers
        Map<String, FB_Sales_Order__c> orderMap = new Map<String, FB_Sales_Order__c>(
            [SELECT Id, Order_Number__c, Status__c, Tracking_Number__c, Carrier__c, Shipped_Date__c
             FROM FB_Sales_Order__c
             WHERE Order_Number__c IN :latestByOrder.keySet()
             AND Status__c != 'Cancelled']
        );

        if (orderMap.isEmpty()) {
            return;
        }

        // Prepare the update list
        List<FB_Sales_Order__c> toUpdate = new List<FB_Sales_Order__c>();
