public class ErpAccountSyncJob implements Queueable {
    private Set<Id> accountIds;
    private Integer attempt;

    public ErpAccountSyncJob(Set<Id> accountIds, Integer attempt) {
        this.accountIds = accountIds;
        this.attempt = attempt;
    }

    private class FinalizerContextImpl implements FinalizerContext {
        private final Boolean success;
        private final Exception ex;

        public FinalizerContextImpl(Boolean success, Exception ex) {
            this.success = success;
            this.ex = ex;
        }

        public Boolean getSuccess() {
            return success;
        }

        public Exception getException() {
            return ex;
        }
    }

    public void execute(QueueableContext context) {
        // Attach the finalizer before doing any work
        ErpSyncFinalizer finalizer = new ErpSyncFinalizer(accountIds, attempt);

        try {
            List<Account> accounts = [SELECT Id, Description FROM Account WHERE Id IN :accountIds];

            for (Account acc : accounts) {
                acc.Description = 'Synced to ERP';
            }

            // Single DML on a collection: all-or-nothing
            update accounts;

            finalizer.execute(new FinalizerContextImpl(true, null));
        } catch (Exception e) {
            finalizer.execute(new FinalizerContextImpl(false, e));
            // Re-throw so the transaction rolls back and no changes are kept
            throw e;
        }
    }
}
