public class LogPurgeJob implements Schedulable {

    public LogPurgeJob() {
    }

    public void execute(SchedulableContext sc) {
        Date thirtyDaysAgo     = Date.today().addDays(-30);
        Date oneEightyDaysAgo  = Date.today().addDays(-180);

        List<FB_Integration_Log__c> logsToDelete = [
            SELECT Id
            FROM FB_Integration_Log__c
            WHERE (
                    (Level__c != 'ERROR' OR Level__c = null OR Level__c = '')
                    AND CreatedDate < :thirtyDaysAgo
                )
                OR (
                    Level__c = 'ERROR'
                    AND CreatedDate < :oneEightyDaysAgo
                )
        ];

        final Integer batchSize = 10000;
        for (Integer i = 0; i < logsToDelete.size(); i += batchSize) {
            Integer batchEnd = Math.min(i + batchSize, logsToDelete.size());
            List<FB_Integration_Log__c> batch = new List<FB_Integration_Log__c>();
            for (Integer j = i; j < batchEnd; j++) {
                batch.add(logsToDelete[j]);
            }
            delete batch;
        }
    }

    public static Id scheduleNightly() {
        String cronExpression = '0 0 2 ? * *';
        return System.schedule('Log purge (nightly)', cronExpression, new LogPurgeJob());
    }
}
