public class Application {

    public static fflib_Application.UnitOfWorkFactory UnitOfWork =
        new fflib_Application.UnitOfWorkFactory(new UnitOfWorkConstructor());
    public static fflib_Application.ServiceFactory Service =
        new fflib_Application.ServiceFactory(new ServiceFactoryImpl());
    public static fflib_Application.SelectorFactory Selector =
        new fflib_Application.SelectorFactory(new SelectorFactoryImpl());
    public static fflib_Application.DomainFactory Domain =
        new fflib_Application.DomainFactory(new DomainFactoryImpl());

    private class UnitOfWorkConstructor implements fflib_ISObjectUnitOfWork.IUnitOfWorkConstructor {
        public fflib_ISObjectUnitOfWork newInstance() {
            fflib_SObjectUnitOfWork uow = new fflib_SObjectUnitOfWork();
            uow.registerSObjectType(Account.SObjectType);
            uow.registerSObjectType(Contact.SObjectType);
            uow.registerSObjectType(Opportunity.SObjectType);
            uow.registerSObjectType(OpportunityContactRole.SObjectType);
            uow.registerRelationship('Contact.AccountId', 'Account.Id');
            uow.registerRelationship('Opportunity.AccountId', 'Account.Id');
            uow.registerRelationship('OpportunityContactRole.OpportunityId', 'Opportunity.Id');
            uow.registerRelationship('OpportunityContactRole.ContactId', 'Contact.Id');
            return uow;
        }
    }

    private class ServiceFactoryImpl implements fflib_IServiceFactory {
        public Object newInstance(String interfaceName) {
            if (interfaceName == 'IAccountsService') {
                return new AccountsServiceImpl();
            }
