public inherited sharing class AccountsSelector extends fflib_SObjectSelector {

    public AccountsSelector() {
        setMode('USER_MODE');
    }

    public Schema.SObjectType getSObjectType() {
        return Account.SObjectType;
    }

    public List<Schema.SObjectField> getSObjectFieldList() {
        List<Schema.SObjectField> fields = new List<Schema.SObjectField>{
            Account.Id,
            Account.Name,
            Account.Industry
        };

        Set<String> fieldNames = new Set<String>{
            'Id',
            'Name',
            'Industry'
        };

        Schema.FieldSetDescribe creditReview = getSObjectType().getDescribe().getFieldSet('Credit_Review');
        if (creditReview != null) {
            for (Schema.FieldSetItemDescribe item : creditReview.getFields()) {
                Schema.SObjectField field = item.getField();
                if (field == null) {
                    continue;
                }
                String fieldName = field.getDescribe().getName();
                if (!fieldNames.add(fieldName)) {
                    continue;
                }
                fields.add(field);
            }
        }

        return fields;
    }

    public List<Account> selectById(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return new List<Account>();
        }
        return (List<Account>) selectSObjectsById(accountIds);
    }

    public List<Account> selectByIdWithContacts(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return new List<Account>();
        }

        List<String> accountFieldNames = new List<String>();
        for (Schema.SObjectField field : getSObjectFieldList()) {
            accountFieldNames.add(field.getDescribe().getName());
        }

        List<String> contactFieldNames = new List<String>();
        for (Schema.SObjectField field : new ContactsSelector().getSObjectFieldList()) {
            contactFieldNames.add(field.getDescribe().getName());
        }
        String contactSubquery = 'SELECT ' + String.join(contactFieldNames, ', ') + ' FROM Contacts';

        String soql = 'SELECT ' + String.join(accountFieldNames, ', ')
            + ' FROM Account WHERE Id IN :accountIds '
            + contactSubquery;

        return (List<Account>) Database.queryWithBoltString(soql, new Map<String, Object>{ 'accountIds' => accountIds });
    }
}
