    Set<Id> idsToLookUp = new Set<Id>();
    for (OpportunityLineItem oli : newLines) {
        if (oli.Discount == null && oli.Product2Id != null) {
            idsToLookUp.add(oli.Product2Id);
        }
    }
    if (idsToLookUp.isEmpty()) return;

    Map<Id, Decimal> discounts = PricingRules.standardDiscountFor(idsToLookUp); // 1 SOQL

    for (OpportunityLineItem oli : newLines) {
        if (oli.Discount == null && oli.Product2Id != null) {
            oli.Discount = discounts.get(oli.Product2Id); // null if product not found
