import { LightningElement, track } from 'lwc';
import searchContacts from '@salesforce/apex/ContactController.searchContacts';

export default class ContactSearch extends LightningElement {
    @track results = [];
    @track errorMessage = '';

    _debounceTimer = null;
    _requestId = 0;

    get hasError() {
        return this.errorMessage !== '';
    }

    get hasResults() {
        return this.results.length > 0;
    }

    disconnectedCallback() {
        if (this._debounceTimer !== null) {
            clearTimeout(this._debounceTimer);
            this._debounceTimer = null;
        }
        // Invalidate any in-flight request so its response is discarded
        this._requestId++;
    }

    handleChange(event) {
        if (this._debounceTimer !== null) {
            clearTimeout(this._debounceTimer);
            this._debounceTimer = null;
        }

        const trimmed = (event.detail.value || '').trim();

        if (trimmed.length < 2) {
            // Cancel any pending search, do not call Apex, clear results
            this._requestId++;
            this.results = [];
            this.errorMessage = '';
            return;
        }

        this._debounceTimer = setTimeout(() => {
            this._debounceTimer = null;
            this._runSearch(trimmed);
        }, 300);
    }

    _runSearch(searchTerm) {
        if (!this.isConnected) {
            return;
        }

        const requestId = ++this._requestId;
        this.errorMessage = '';

        searchContacts({ searchTerm })
            .then((contacts) => {
                if (!this.isConnected || requestId !== this._requestId) {
                    return;
                }
                this.results = contacts || [];
            })
            .catch((error) => {
                if (!this.isConnected || requestId !== this._requestId) {
                    return;
                }
                this.results = [];
                this.errorMessage = error.body.message;
            });
    }
}
