import { LightningElement, wire } from 'lwc';
import {
    LightningMessageContext,
    subscribe,
    unsubscribe,
    publish,
    APPLICATION_SCOPE
} from 'lightning/messageService';
import Account_Selected__c from '@salesforce/messageChannel/Account_Selected__c';

export default class AccountDetailsPanel extends LightningElement {
    selectedRecordId;
    _messageContext;
    _subscription;

    get hasSelectedRecord() {
        return !!this.selectedRecordId;
    }

    @wire(LightningMessageContext)
    wiredContext({ value }) {
        if (value) {
            this._messageContext = value;
            if (this.isConnected && !this._subscription) {
                this.subscribeToChannel();
            }
        }
    }

    connectedCallback() {
        if (this._messageContext && !this._subscription) {
            this.subscribeToChannel();
        }
    }

    disconnectedCallback() {
        if (this._subscription) {
            unsubscribe(this._messageContext, this._subscription);
            this._subscription = null;
        }
    }

    subscribeToChannel() {
        this._subscription = subscribe(
            this._messageContext,
            Account_Selected__c,
            (message) => this.handleMessage(message),
            { scope: APPLICATION_SCOPE }
        );
    }

    handleMessage(message) {
        if (message && message.recordId) {
            this.selectedRecordId = message.recordId;
        } else {
            this.selectedRecordId = null;
        }
    }

    handleClear(event) {
        event.preventDefault();
        publish(
            this._messageContext,
            Account_Selected__c,
            { recordId: null },
            { scope: APPLICATION_SCOPE }
        );
    }
}
