    handleReset() {
        const editors = this.template.querySelectorAll('c-line-item-editor');
        editors.forEach((editor) => {
            editor.reset();
        });
    }

    handleSubmit() {
        const editors = this.template.querySelectorAll('c-line-item-editor');
        let allValid = true;

        // Validate every editor so that all invalid lines show their errors at once.
        editors.forEach((editor) => {
            const valid = editor.validate();
            if (!valid) {
                allValid = false;
            }
        });

        if (allValid) {
            this.showError = false;
            const values = editors.map((editor) => editor.getValue());
            this.dispatchEvent(
                new CustomEvent('submit', {
                    bubbles: true,
                    composed: true,
                    detail: { lines: values }
                })
            );
        } else {
            this.showError = true;
        }
    }
}
