import { LightningElement } from 'lwc';
import register from '@salesforce/apex/RegistrationController.register';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';

export default class EventRegistrationForm extends LightningElement {
    fullName = '';
    email = '';
    company = '';

    handleFieldChange(event) {
        const field = event.target.dataset.field;
        this[field] = event.detail.value;
    }

    handleRegister() {
        const inputs = Array.from(this.template.querySelectorAll('lightning-input'));
        const emailInput = this.template.querySelector('[data-field="email"]');

        // Step 1: Validate email domain before reporting validity
        const emailValue = this.email || '';
        const atIndex = emailValue.lastIndexOf('@');
        if (atIndex !== -1) {
            const domain = emailValue.substring(atIndex + 1).toLowerCase();
            const personalDomains = ['gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com'];
            if (personalDomains.includes(domain)) {
                emailInput.setCustomValidity('Use your work email address.');
            } else {
                emailInput.setCustomValidity('');
            }
        } else {
            emailInput.setCustomValidity('');
        }

        // Step 2: Report validity on every input so all invalid fields show their messages
        inputs.forEach((input) => input.reportValidity());

        // Step 3: If any input is invalid, stop
        if (!inputs.every((input) => input.checkValidity())) {
            return;
        }

        // Step 4: Call register imperatively
        register({ fullName: this.fullName, email: this.email, company: this.company })
            .then(() => {
                this.dispatchEvent(
                    new ShowToastEvent({
                        title: 'Registered',
                        message: 'You have been registered for the event.',
                        variant: 'success'
                    })
                );
            })
            .catch((error) => {
                this.dispatchEvent(
                    new ShowToastEvent({
                        title: 'Registration failed',
                        message: error.body.message,
                        variant: 'error'
                    })
                );
            });
    }
}
