    get activeDescendantId() {
        if (!this._options || this._options.length === 0) {
            return '';
        }
        return 'option-' + this._activeIndex;
    }

    get displayOptions() {
        return (this._options || []).map((opt, i) => ({
            id: 'option-' + i,
            value: opt.value,
            label: opt.label,
            selected: opt.value === this._value
        }));
    }

    connectedCallback() {
        this._updateActiveIndex();
    }

    _updateActiveIndex() {
        if (!this._options || this._options.length === 0) {
            this._activeIndex = 0;
            return;
        }
        const idx = this._options.findIndex((o) => o.value === this._value);
        this._activeIndex = idx >= 0 ? idx : 0;
    }

    handleKeydown(event) {
        const key = event.key;
        const handled = ['ArrowDown', 'ArrowUp', 'Home', 'End', 'Enter', ' '];
        if (!handled.includes(key)) {
            return;
        }
        event.preventDefault();

        if (!this._options || this._options.length === 0) {
            return;
        }

        switch (key) {
            case 'ArrowDown':
                if (this._activeIndex < this._options.length - 1) {
                    this._activeIndex++;
                }
                break;
            case 'ArrowUp':
                if (this._activeIndex > 0) {
                    this._activeIndex--;
                }
                break;
            case 'Home':
                this._activeIndex = 0;
                break;
            case 'End':
                this._activeIndex = this._options.length - 1;
                break;
            case 'Enter':
            case ' ':
                this._selectOption(this._activeIndex);
                break;
        }
    }

    handleClick(event) {
        const val = event.currentTarget.dataset.value;
        const idx = this._options.findIndex((o) => String(o.value) === val);
        if (idx >= 0) {
            this._activeIndex = idx;
            this._selectOption(idx);
        }
    }

    _selectOption(index) {
        const opt = this._options[index];
        if (!opt) {
            return;
        }
        if (opt.value === this._value) {
            return;
        }
        this._value = opt.value;
        this._activeIndex = index;
        this.dispatchEvent(
            new CustomEvent('change', { detail: { value: opt.value } })
        );
    }
}
