import { LightningElement, api, track } from 'lwc';

export default class StatusListbox extends LightningElement {
    @api label;

    @track _options = [];
    @track _value = '';
    @track _activeIndex = 0;

    @api
    get options() {
        return this._options;
    }
    set options(val) {
        this._options = Array.isArray(val) ? val : [];
        this._syncActiveIndex();
    }

    @api
    get value() {
        return this._value;
    }
    set value(val) {
        this._value = val;
        this._syncActiveIndex();
    }

    get items() {
        return this._options.map((opt, i) => ({
            id: `statusListbox-option-${i}`,
            value: opt.value,
            label: opt.label,
            selected: opt.value === this._value
        }));
    }

    get activeDescendantId() {
        if (this._options.length === 0) {
            return '';
        }
        return `statusListbox-option-${this._activeIndex}`;
    }

    _syncActiveIndex() {
        if (this._options.length === 0) {
            this._activeIndex = 0;
            return;
        }
        const idx = this._options.findIndex((opt) => opt.value === this._value);
        this._activeIndex = idx !== -1 ? idx : 0;
    }

    handleKeydown(event) {
        const { key } = event;
        const handled = ['ArrowDown', 'ArrowUp', 'Home', 'End', 'Enter', ' '];

        if (handled.indexOf(key) === -1) {
            return;
        }

        event.preventDefault();

        const len = this._options.length;
        if (len === 0) {
            return;
        }

        switch (key) {
            case 'ArrowDown':
                this._activeIndex = Math.min(this._activeIndex + 1, len - 1);
                break;
            case 'ArrowUp':
                this._activeIndex = Math.max(this._activeIndex - 1, 0);
                break;
            case 'Home':
                this._activeIndex = 0;
                break;
            case 'End':
                this._activeIndex = len - 1;
                break;
            case 'Enter':
            case ' ':
                this._selectOption(this._activeIndex);
                break;
        }
    }

    handleClick(event) {
        const id = event.target.id;
        const idx = this._options.findIndex((opt, i) => `statusListbox-option-${i}` === id);
        if (idx !== -1) {
            this._selectOption(idx);
        }
    }

    _selectOption(index) {
        const option = this._options[index];
        if (!option) {
            return;
        }
        this._activeIndex = index;
        if (option.value === this._value) {
            return;
        }
        this._value = option.value;
        this.dispatchEvent(
            new CustomEvent('change', {
                detail: { value: option.value }
            })
        );
    }
}
