public class GiftImportService {

    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;
        public Decimal amount;
        public Date giftDate;
    }

    public class ImportResult {
        public Boolean success;
        public Id contactId;
        public Id opportunityId;
        public String errorMessage;
    }

    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        if (gifts == null || gifts.isEmpty()) {
            return new List<ImportResult>();
        }

        // ---- 1. Stage one npsp__DataImport__c record per gift ----
        List<npsp__DataImport__c> dataImports = new List<npsp__DataImport__c>();
        for (WebGift gift : gifts) {
            npsp__DataImport__c di = new npsp__DataImport__c();
            di.npsp__Contact1_Firstname__c      = gift.firstName;
            di.npsp__Contact1_Lastname__c       = gift.lastName;
            di.npsp__Contact1_Personal_Email__c = gift.email;
            di.npsp__Donation_Amount__c         = gift.amount;
            di.npsp__Donation_Date__c           = gift.giftDate;
            di.npsp__Donation_Donor__c          = 'Contact1';
            dataImports.add(di);
        }
        insert dataImports;

        // ---- 2. Collect IDs of the staged records ----
        List<ID> importIds = new List<ID>(dataImports.size());
        for (npsp__DataImport__c di : dataImports) {
            importIds.add(di.Id);
        }

        // ---- 3. Process synchronously via NPSP's Batch Data Import ----
        // Runs in the same transaction; applies the org's Data Import Settings
        // (matching on first name / last name / email, never matching donations).
        Database.executeBatch(new npsp__BatchDataImport(), dataImports.size());

        // ---- 4. Query back the processed records ----
        Map<ID, npsp__DataImport__c> processedMap = new Map<ID, npsp__DataImport__c>(
            [SELECT Id,
                    npsp__Status__c,
                    npsp__Contact1Imported__c,
                    npsp__DonationImported__c,
                    npsp__FailureInformation__c
             FROM npsp__DataImport__c
             WHERE Id IN :importIds]
        );

        // ---- 5. Build ImportResult list in input order ----
        List<ImportResult> results = new List<ImportResult>();
        for (npsp__DataImport__c di : dataImports) {
            ImportResult result = new ImportResult();
            npsp__DataImport__c processed = processedMap.get(di.Id);

            if (processed != null
                && String.valueOf(processed.npsp__Status__c).equalsIgnoreCase('Imported')) {
                result.success       = true;
                result.contactId     = processed.npsp__Contact1Imported__c;
                result.opportunityId = processed.npsp__DonationImported__c;
            } else {
                result.success = false;
                result.errorMessage = (processed != null)
                    ? processed.npsp__FailureInformation__c
                    : 'Unknown processing error';
            }
            results.add(result);
        }

        return results;
    }
}
