/**
 * GiftImportService
 *
 * Routes one-off website gifts through the NPSP Data Importer (BDI) so that
 * NPSP's contact matching, household creation and donation-processing rules
 * apply, and each staged Data Import record remains in the org as an audit
 * trail of what was imported.
 *
 * Each WebGift is staged as a single npsp__DataImport__c row with the donor
 * in Contact1 and the donation in the Donation_* fields. The rows are then
 * processed synchronously, in the same transaction, via NPSP's Data Importer
 * Apex API (DataImporter.run(..., sync = true)), which honours the org's
 * npsp__Data_Import_Settings__c hierarchy custom setting. With the default
 * settings the importer matches existing contacts on first name, last name
 * and personal email and does not match existing donations, so a new
 * Opportunity is created for every gift.
 *
 * A failure on one row never stops the others: NPSP marks the rejected row
 * with npsp__Status__c = 'Failed' and npsp__FailureInformation__c, and that
 * message is surfaced on the matching ImportResult.
 */
public class GiftImportService {

    // NPSP Data Import object / fields.
    private static final String DATA_IMPORT_OBJ = 'npsp__DataImport__c';

    private static final String FIELD_STATUS              = 'npsp__Status__c';
    private static final String FIELD_CONTACT1_FIRSTNAME  = 'npsp__Contact1_Firstname__c';
    private static final String FIELD_CONTACT1_LASTNAME   = 'npsp__Contact1_Lastname__c';
    private static final String FIELD_CONTACT1_EMAIL      = 'npsp__Contact1_Personal_Email__c';
    private static final String FIELD_DONATION_AMOUNT     = 'npsp__Donation_Amount__c';
    private static final String FIELD_DONATION_DATE       = 'npsp__Donation_Date__c';
    private static final String FIELD_DONATION_DONOR      = 'npsp__Donation_Donor__c';
    private static final String FIELD_CONTACT1_IMPORTED   = 'npsp__Contact1Imported__c';
    private static final String FIELD_DONATION_IMPORTED   = 'npsp__DonationImported__c';
    private static final String FIELD_FAILURE_INFORMATION = 'npsp__FailureInformation__c';

    // Status value written by NPSP for rows it successfully imported.
    private static final String STATUS_IMPORTED = 'Imported';

    /**
     * Stages one NPSP Data Import record per gift and processes them
     * synchronously through the NPSP Data Importer in the current
     * transaction. Returns one ImportResult per gift, in input order.
     *
     * A null or empty input list returns an empty list.
     */
    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        if (gifts == null || gifts.isEmpty()) {
            return new List<ImportResult>();
        }

        // --- 1. Stage a Data Import record per gift --------------------------
        Map<Id, Integer> giftIndexById = new Map<Id, Integer>();
        List<npsp__DataImport__c> stagedRecords = new List<npsp__DataImport__c>(gifts.size());

        for (Integer i = 0; i < gifts.size(); i++) {
            WebGift gift = gifts.get(i);
            npsp__DataImport__c di = new npsp__DataImport__c(
                FIELD_CONTACT1_FIRSTNAME = (gift != null ? gift.firstName  : null),
                FIELD_CONTACT1_LASTNAME  = (gift != null ? gift.lastName   : null),
                FIELD_CONTACT1_EMAIL     = (gift != null ? gift.email      : null),
                FIELD_DONATION_AMOUNT    = (gift != null ? gift.amount     : null),
                FIELD_DONATION_DATE      = (gift != null ? gift.giftDate   : null),
                FIELD_DONATION_DONOR     = 'Contact1',
                FIELD_STATUS             = 'Pending'
            );
            stagedRecords.add(di);
            giftIndexById.put(di.Id, i);
        }

        insert stagedRecords;

        // --- 2. Process synchronously via NPSP's Data Importer --------------
        // sync = true: NPSP runs the import in this transaction and writes
        // npsp__Status__c, npsp__Contact1Imported__c, npsp__DonationImported__c
        // and npsp__FailureInformation__c back onto each staged row.
        DataImporter.run(stagedRecords, null, true);

        // --- 3. Read the results back off the staged rows -------------------
        Set<Id> recordIds = new Set<Id>(giftIndexById.keySet());
        List<npsp__DataImport__c> processed = [
            SELECT
                Id,
                npsp__Status__c,
                npsp__Contact1Imported__c,
                npsp__DonationImported__c,
                npsp__FailureInformation__c
            FROM npsp__DataImport__c
            WHERE Id IN :recordIds
        ];

        Map<Id, npsp__DataImport__c> byId = new Map<Id, npsp__DataImport__c>();
        for (npsp__DataImport__c rec : processed) {
            byId.put(rec.Id, rec);
        }

        // --- 4. Build one result per gift, in input order --------------------
        List<ImportResult> results = new List<ImportResult>(gifts.size());
        for (Integer i = 0; i < gifts.size(); i++) {
            Id recordId = stagedRecords.get(i).Id;
            npsp__DataImport__c rec = byId.get(recordId);

            ImportResult r = new ImportResult();
            if (rec == null) {
                r.success = false;
                r.errorMessage = 'NPSP Data Import record was not processed.';
            } else if (String.valueOf(rec.npsp__Status__c) == STATUS_IMPORTED) {
                r.success       = true;
                r.contactId     = rec.npsp__Contact1Imported__c;
                r.opportunityId = rec.npsp__DonationImported__c;
            } else {
                r.success      = false;
                r.errorMessage = rec.npsp__FailureInformation__c != null
                    ? rec.npsp__FailureInformation__c
                    : ('NPSP Data Import failed with status: ' + rec.npsp__Status__c);
            }
            results.add(r);
        }

        return results;
    }

    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;        // the donor's personal email
        public Decimal amount;
        public Date giftDate;
    }

    public class ImportResult {
        public Boolean success;
        public Id contactId;        // the matched or created contact
        public Id opportunityId;    // the created donation
        public String errorMessage; // NPSP's failure information when success is false
    }
}
