public class GauAllocationService {

    public class AllocationException extends Exception {}

    public static List<npsp__Allocation__c> allocateByPercent(Id opportunityId, Map<Id, Decimal> percentByGauId) {

        // ── Validation (before any DML) ──────────────────────────────────────

        if (percentByGauId == null || percentByGauId.isEmpty()) {
            throw new AllocationException('percentByGauId must not be null or empty.');
        }

        Decimal totalPercent = 0;
        Set<Id> gauIds = new Set<Id>();

        for (Id gauId : percentByGauId.keySet()) {
            Decimal pct = percentByGauId.get(gauId);
            if (pct == null || pct <= 0) {
                throw new AllocationException(
                    'Each percentage must be greater than 0. Invalid value: ' + pct + ' for GAU: ' + gauId);
            }
            totalPercent += pct;
            gauIds.add(gauId);
        }

        if (totalPercent > 100) {
            throw new AllocationException(
                'Total percentages cannot exceed 100. Total: ' + totalPercent + '%.');
        }

        // Check that every GAU exists and is active
        List<npsp__General_Accounting_Unit__c> gaus = [
            SELECT Id, Name, npsp__Active__c
            FROM npsp__General_Accounting_Unit__c
            WHERE Id IN :gauIds
        ];

        Map<Id, npsp__General_Accounting_Unit__c> gauById = new Map<Id, npsp__General_Accounting_Unit__c>(gaus);

        for (Id gauId : gauIds) {
            if (!gauById.containsKey(gauId)) {
                throw new AllocationException('GAU not found: ' + gauId);
            }
            if (!gauById.get(gauId).npsp__Active__c) {
                throw new AllocationException(
                    'GAU is inactive: ' + gauById.get(gauId).Name + ' (' + gauId + ').');
            }
        }

        // ── Load opportunity (needed for current amount) ─────────────────────

        Opportunity opp = [SELECT Id, Amount FROM Opportunity WHERE Id = :opportunityId LIMIT 1];
        if (opp == null) {
            throw new AllocationException('Opportunity not found: ' + opportunityId);
        }

        Decimal oppAmount = opp.Amount != null ? opp.Amount : 0;

        // ── DML: replace existing allocations ────────────────────────────────

        List<npsp__Allocation__c> existingAllocations = [
            SELECT Id
            FROM npsp__Allocation__c
            WHERE npsp__Opportunity__c = :opportunityId
        ];

        if (!existingAllocations.isEmpty()) {
            delete existingAllocations;
        }

        // ── Build and insert new allocations ─────────────────────────────────
        // Setting npsp__Percent__c ensures NPSP recalculates npsp__Amount__c
        // automatically whenever the Opportunity.Amount changes later.

        List<npsp__Allocation__c> newAllocations = new List<npsp__Allocation__c>();

        for (Id gauId : percentByGauId.keySet()) {
            Decimal pct = percentByGauId.get(gauId);
            npsp__Allocation__c alloc = new npsp__Allocation__c(
                npsp__Opportunity__c             = opportunityId,
                npsp__General_Accounting_Unit__c = gauId,
                npsp__Percent__c                = pct,
                npsp__Amount__c                 = oppAmount * (pct / 100)
            );
            newAllocations.add(alloc);
        }

        insert newAllocations;

        return newAllocations;
    }
}
