public class PaymentPlanService {

    public class PaymentPlanException extends Exception {}

    public static List<npe01__OppPayment__c> scheduleInstallments(
        Id opportunityId,
        Integer numberOfPayments,
        Date firstPaymentDate
    ) {
        // --- Validation (before any DML) ---

        if (numberOfPayments == null || numberOfPayments < 1) {
            throw new PaymentPlanException(
                'numberOfPayments must be a positive integer (got: ' + numberOfPayments + ').'
            );
        }

        Opportunity opp = [
            SELECT Id, Amount, IsClosed,
                   (SELECT Id, npe01__Payment_Amount__c,
                            npe01__Paid__c, npe01__Written_Off__c
                    FROM npe01__OppPayment__r)
            FROM Opportunity
            WHERE Id = :opportunityId
        ];

        if (opp.IsClosed) {
            throw new PaymentPlanException(
                'Cannot schedule installments on a closed opportunity (' + opportunityId + ').'
            );
        }

        // --- Compute outstanding and identify payments to delete ---

        Decimal paidAndWrittenOffTotal = 0;
        List<npe01__OppPayment__c> paymentsToDelete = new List<npe01__OppPayment__c>();

        for (npe01__OppPayment__c p : opp.npe01__OppPayment__r) {
            if (p.npe01__Paid__c == true || p.npe01__Written_Off__c == true) {
                // History – leave untouched
                paidAndWrittenOffTotal += (p.npe01__Payment_Amount__c == null ? 0 : p.npe01__Payment_Amount__c);
            } else {
                // Unpaid and not written off – will be replaced
                paymentsToDelete.add(p);
            }
        }

        Decimal opportunityAmount = (opp.Amount == null ? 0 : opp.Amount);
        Decimal outstanding = opportunityAmount - paidAndWrittenOffTotal;

        if (outstanding <= 0) {
            throw new PaymentPlanException(
                'Outstanding amount must be greater than zero (got: ' + outstanding + ').'
            );
        }

        // --- Calculate per-payment amount (rounded down to the cent) ---

        // (outstanding * 100) / numberOfPayments, floored, then / 100 to get back to dollars
        Decimal perPayment = (Decimal) Math.floor((Double)(outstanding * 100) / numberOfPayments) / 100;

        // --- Build the new payment records ---

        List<npe01__OppPayment__c> newPayments = new List<npe01__OppPayment__c>();
        Decimal allocated = 0;

        for (Integer i = 0; i < numberOfPayments; i++) {
            npe01__OppPayment__c p = new npe01__OppPayment__c();
            p.npe01__Opportunity__c    = opportunityId;
            p.npe01__Scheduled_Date__c = firstPaymentDate.addMonths(i);
            p.npe01__Paid__c           = false;

            if (i == numberOfPayments - 1) {
                // Last payment absorbs any rounding remainder
                p.npe01__Payment_Amount__c = outstanding - allocated;
            } else {
                p.npe01__Payment_Amount__c = perPayment;
                allocated += perPayment;
            }

            newPayments.add(p);
        }

        // --- DML ---

        if (!paymentsToDelete.isEmpty()) {
            Delete paymentsToDelete;
        }

        Insert newPayments;

        return newPayments;
